#include "continuous_runtime.hpp"
#include <thread>
namespace exotic::runtime {ContinuousOperationsRuntime::ContinuousOperationsRuntime(RuntimeConfig c,TelemetryRepository&r,EmergencyCoordinator&e,FailureInjector*i):config_(std::move(c)),workspace_(config_.workspace),repo_(r),audit_(r,config_.workspace_id),metrics_(r,config_.workspace_id),dashboard_(workspace_.paths().dashboards),emergency_(e),supervisor_(lifecycle_,r,dashboard_,config_,e),control_(r,config_.workspace_id),injector_(i){}void ContinuousOperationsRuntime::add_service(std::shared_ptr<RuntimeService>s){lifecycle_.add(std::move(s));}void ContinuousOperationsRuntime::start(){if(started_.exchange(true))return;if(injector_)injector_->check("runtime.before_lock");lease_=std::make_unique<WorkspaceLease>(workspace_.paths());audit_.emit("lifecycle","runtime","workspace",config_.workspace_id,"Runtime starting");try{if(injector_)injector_->check("runtime.before_recovery");lifecycle_.recover_all();audit_.emit("recovery","runtime","workspace",config_.workspace_id,"All services recovered");if(injector_)injector_->check("runtime.before_start");lifecycle_.start_all();supervisor_.start();metrics_.record("runtime.started",1,"count");audit_.emit("lifecycle","runtime","workspace",config_.workspace_id,"Runtime started");}catch(...){started_=false;lease_.reset();throw;}}void ContinuousOperationsRuntime::request_stop(){if(!started_)return;audit_.emit("lifecycle","runtime","workspace",config_.workspace_id,"Runtime stop requested");supervisor_.request_stop();lifecycle_.request_stop();}void ContinuousOperationsRuntime::join(){if(!started_)return;supervisor_.join();lifecycle_.join();audit_.emit("lifecycle","runtime","workspace",config_.workspace_id,"Runtime stopped cleanly");metrics_.record("runtime.stopped",1,"count");control_.clear_command("shutdown");lease_.reset();started_=false;}void ContinuousOperationsRuntime::process_controls(){if(auto c=control_.emergency_request()){if(c->value=="activate")emergency_.activate(c->actor,c->reason);else emergency_.clear(c->actor,c->reason);control_.clear_command("emergency");}if(control_.shutdown_requested())request_stop();}void ContinuousOperationsRuntime::run(std::stop_token stop){start();while(started_&&!stop.stop_requested()&&lifecycle_.running()){process_controls();if(control_.shutdown_requested())break;std::this_thread::sleep_for(config_.control_interval);}request_stop();join();}RuntimeSnapshot ContinuousOperationsRuntime::snapshot(){return supervisor_.snapshot();}}
